		this.maxLitterSize = maxLitterSize;
		this.maxFoodHunger = maxFoodHunger;
		this.initialHunger = initialHunger;
		this.breedingProbability = breedingProbability;
		this.creationProbability = creationProbability;

	} 


	/**
