14	    /**
15	     * Function which creates all the players for a field 
16	     * @param field the field for which all the simulatables will be generated
17	     * @return the list of all simulatable objects
18	     */
19		public ArrayList<Simulatable> createPlayers(Field field) {
20			
21			ArrayList<Simulatable> simulatables = new ArrayList<>();
22			for(int row = 0; row < field.getDepth(); row++) {
23	            for(int col = 0; col < field.getWidth(); col++) {
24	                Disease disease = generateDisease(); // Get a disease (could be null) to give the animal 
25	                if(rand.nextDouble() <= Racoon.POPULATION_CONTROLS.getCreationProbability()) {
26	                    Location location = new Location(row, col);
27	                    Racoon racoon = new Racoon(true, field, location);
28	                    racoon.forceDisease(disease);//Give the animal a disease
29	                    simulatables.add(racoon);
30	                } 
31	                else if(rand.nextDouble() <= Hawk.POPULATION_CONTROLS.getCreationProbability()) {
32	                    Location location = new Location(row, col);
33	                    Hawk mouse = new Hawk(true, field, location);
34	                    mouse.forceDisease(disease);
35	                    simulatables.add(mouse);
36	                }
37	                else if(rand.nextDouble() <= Mouse.POPULATION_CONTROLS.getCreationProbability()) {
38	                    Location location = new Location(row, col);
39	                    Mouse mouse = new Mouse(true, field, location);
40	                    mouse.forceDisease(disease);
41	                    simulatables.add(mouse);
42	                }
43	                else if(rand.nextDouble() <= Rat.POPULATION_CONTROLS.getCreationProbability()) {
44	                    Location location = new Location(row, col);
45	                    Rat mouse = new Rat(true, field, location);
46	                    mouse.forceDisease(disease);
47	                    simulatables.add(mouse);
48	                }
49	                else if(rand.nextDouble() <= Squirrel.POPULATION_CONTROLS.getCreationProbability()) {
50	                    Location location = new Location(row, col);
